#pragma once
#include <string>
#include <sstream>
#include <iomanip>
namespace indicators {
class ProgressBar {
public:
  ProgressBar()
    : progress_(0), total_(100), width_(50),
      show_percentage_(true), show_bar_(true),
      fill_("="), lead_(">"), remainder_(" "), start_("["), end_("]") {}
  void set_progress(int p){progress_=p;}
  void set_total(int t){total_=t;}
  void set_width(int w){width_=w;}
  std::string str() const {
    std::ostringstream oss;
    if (show_bar_) {
      oss << start_;
      int pos = static_cast<int>(static_cast<float>(progress_) / static_cast<float>(total_) * static_cast<float>(width_));
      for (int i = 0; i < width_; ++i) {
        if (pos > i) oss << fill_;
        else if (pos == i) oss << lead_;
        else oss << remainder_;
      }
      oss << end_;
    }
    if (show_percentage_) {
      if (show_bar_) oss << " ";
      oss << std::fixed << std::setprecision(1)
          << (static_cast<float>(progress_) / static_cast<float>(total_)) * 100.0 << "%";
    }
    return oss.str();
  }
private:
  int progress_, total_, width_;
  bool show_percentage_, show_bar_;
  std::string fill_, lead_, remainder_, start_, end_;
};
class Percentage {
public:
  explicit Percentage(float v) : value_(v) {}
  std::string str() const {
    std::ostringstream oss;
    oss << std::fixed << std::setprecision(1) << value_ * 100.0 << "%";
    return oss.str();
  }
private:
  float value_;
};
}
EOF
